    def pos_of(v):
        if isinstance(v, dict):
            if 'x' in v and 'y' in v:
                return [v.get('x'), v.get('y')]
            for k1, k2 in (('pos', None), ('position', None), ('location', None), ('loc', None), ('self', None), ('agent', None), ('me', None)):
                if k1 in v:
                    p = pos_of(v.get(k1))
                    if p is not None:
                        return p
            return None
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [a, b]
        return None

    def add_positions(out, v):
        p = pos_of(v)
        if p is not None:
            out.append(p)
            return
        if isinstance(v, dict):
            for vv in v.values():
                add_positions(out, vv)
        elif isinstance(v, (list, tuple)):
            for vv in v:
                add_positions(out, vv)

