        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def pick_first(*keys):
        for k in keys:
            if isinstance(observation, dict) and k in observation:
                return observation.get(k)
        return None

    me = None
    for k in ('position', 'agent_pos', 'agent_position', 'self', 'player', 'me', 'loc', 'location'):
        if isinstance(observation, dict) and k in observation:
            me = pos_of(observation.get(k))
            if me is not None:
                break
    if me is None and isinstance(observation, dict):
        me = pos_of(observation.get('agent')) or pos_of(observation.get('player_state'))
    if me is None:
        return [0, 0]

    targets = []
    threats = []

    for k in ('resources', 'resource_positions', 'food', 'collectibles', 'treasures', 'goals', 'goal_positions',
              'objective', 'objectives', 'target', 'targets', 'frontier', 'unclaimed', 'neutral', 'enemy_base',
              'opponent_base', 'home', 'capsules', 'pickups'):
        if isinstance(observation, dict) and k in observation:
            add_positions(targets, observation.get(k))

    for k in ('enemies', 'enemy', 'opponents', 'opponent', 'pursuers', 'hunters', 'hostiles', 'threats'):
        if isinstance(observation, dict) and k in observation:
            add_positions(threats, observation.get(k))

